import { defineConfig } from 'vite';

export default defineConfig({
  base: './',
  server: {
    host: '0.0.0.0',
    port: 3002,
    strictPort: true,
  },
  build: {
    target: 'es2020',
    chunkSizeWarningLimit: 1600,
  },
});

import * as THREE from 'three';

// Sunset City is an original, procedural open-world driving sandbox.
const canvas = document.querySelector('#game');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x9aa9b6);
scene.fog = new THREE.FogExp2(0xaaa9a1, 0.00155);
const camera = new THREE.PerspectiveCamera(57, innerWidth / innerHeight, 0.1, 1200);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.7));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.setClearColor(0xa6a7a5);

const clock = new THREE.Clock();
const mat = (color, roughness = 0.8, metalness = 0) => new THREE.MeshStandardMaterial({ color, roughness, metalness });
const mats = {
  asphalt: mat(0x343b3e, 0.96), sidewalk: mat(0xaaa59b, 0.92), concrete: mat(0x777a76, 0.92),
  white: mat(0xe5e2d9, 0.55), dark: mat(0x191e21, 0.6), rubber: mat(0x17191a, 0.98),
  glass: new THREE.MeshPhysicalMaterial({ color: 0x9bb7be, roughness: 0.2, metalness: 0.2, transparent: true, opacity: 0.48, side: THREE.DoubleSide }),
  gold: new THREE.MeshStandardMaterial({ color: 0xd7b77d, metalness: 0.65, roughness: 0.32 }),
  leaf: mat(0x314c3f, 0.94), leaf2: mat(0x52654d, 0.96), trunk: mat(0x5b4536, 0.95),
  lane: new THREE.MeshBasicMaterial({ color: 0xd6cda9 }),
};
const boxGeo = new THREE.BoxGeometry(1, 1, 1);
const cylGeo = new THREE.CylinderGeometry(1, 1, 1, 12);
const sphereGeo = new THREE.SphereGeometry(1, 16, 10);
function addBox(parent, material, x, y, z, sx, sy, sz, cast = true, receive = true) {
  const mesh = new THREE.Mesh(boxGeo, material);
  mesh.position.set(x, y, z); mesh.scale.set(sx, sy, sz); mesh.castShadow = cast; mesh.receiveShadow = receive;
  parent.add(mesh); return mesh;
}
function addCyl(parent, material, x, y, z, radius, height, radial = 10) {
  const mesh = new THREE.Mesh(radial === 10 ? cylGeo : new THREE.CylinderGeometry(radius, radius, height, radial), material);
  mesh.position.set(x, y, z); mesh.scale.set(radius, height, radius); mesh.castShadow = true; parent.add(mesh); return mesh;
}
function seeded(seed) { let t = seed >>> 0; return () => { t += 0x6D2B79F5; let a=t; a=Math.imul(a^(a>>>15),a|1); a^=a+Math.imul(a^(a>>>7),a|61); return ((a^(a>>>14))>>>0)/4294967296; }; }
const rand = seeded(83821);

// Natural twilight lighting, a soft sun disk and distant atmospheric skyline.
scene.add(new THREE.HemisphereLight(0xc9d9e6, 0x51483e, 1.25));
const sun = new THREE.DirectionalLight(0xffd0a0, 3.2);
sun.position.set(-100, 145, 95); sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048); sun.shadow.camera.left = -115; sun.shadow.camera.right = 115; sun.shadow.camera.top = 115; sun.shadow.camera.bottom = -115;
sun.shadow.bias = -0.00022; sun.shadow.normalBias = 0.03; sun.shadow.radius = 3;
scene.add(sun); scene.add(sun.target);
const fill = new THREE.DirectionalLight(0x8db5df, 0.8); fill.position.set(65, 50, -90); scene.add(fill);
const skyDome = new THREE.Mesh(new THREE.SphereGeometry(850, 32, 18), new THREE.ShaderMaterial({ side: THREE.BackSide, depthWrite: false, uniforms: { topColor: { value: new THREE.Color(0x29435e) }, midColor: { value: new THREE.Color(0x9b9792) }, horizonColor: { value: new THREE.Color(0xf0b28a) }, offset: { value: 30 }, exponent: { value: 0.48 } }, vertexShader: 'varying vec3 vWorldPosition; void main(){ vec4 w=modelMatrix*vec4(position,1.0); vWorldPosition=w.xyz; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0); }', fragmentShader: 'uniform vec3 topColor; uniform vec3 midColor; uniform vec3 horizonColor; uniform float offset; uniform float exponent; varying vec3 vWorldPosition; void main(){ float h=normalize(vWorldPosition+vec3(0.0,offset,0.0)).y; float a=pow(max(h,0.0),exponent); vec3 c=mix(midColor,topColor,smoothstep(0.02,0.65,a)); c=mix(horizonColor,c,smoothstep(-0.02,0.16,h)); gl_FragColor=vec4(c,1.0); }' }));
skyDome.position.y = -60; scene.add(skyDome);
const sunBall = new THREE.Mesh(new THREE.SphereGeometry(15, 20, 14), new THREE.MeshBasicMaterial({ color: 0xffc28f }));
sunBall.position.set(-185, 87, -510); scene.add(sunBall);
const ground = new THREE.Mesh(new THREE.PlaneGeometry(1800, 1800), mat(0x777c78, 0.98));
ground.rotation.x = -Math.PI / 2; ground.position.y = -0.18; ground.receiveShadow = true; scene.add(ground);

// Downtown street grid: broad avenues, parking lanes, sidewalks and crossings.
const CITY_BOUND = 310, BLOCK = 64, ROAD = 18, HALF_ROAD = ROAD / 2;
const roadMat = mats.asphalt;
function makeRoads() {
  for (let k = -4; k <= 4; k++) {
    const p = k * BLOCK;
    addBox(scene, roadMat, p, -0.07, 0, ROAD, 0.18, CITY_BOUND * 2, false);
    addBox(scene, roadMat, 0, -0.065, p, CITY_BOUND * 2, 0.18, ROAD, false);
    // Dashed center lines, double yellow on the major avenues.
    const lineMat = Math.abs(k) < 2 ? new THREE.MeshBasicMaterial({ color: 0xd5b85f }) : mats.lane;
    for (let s = -9; s <= 9; s++) {
      const q = s * 31 + 14;
      addBox(scene, lineMat, p, 0.03, q, 0.12, 0.012, 8, false, false);
      addBox(scene, lineMat, q, 0.03, p, 8, 0.012, 0.12, false, false);
    }
    // Concrete sidewalks and curb strips run along both sides of each boulevard.
    for (const sign of [-1, 1]) {
      const edge = p + sign * (HALF_ROAD + 3.1);
      if (Math.abs(edge) < CITY_BOUND) {
        addBox(scene, mats.sidewalk, edge, 0.02, 0, 5.2, 0.28, CITY_BOUND * 2, false, true);
        addBox(scene, mats.sidewalk, 0, 0.02, edge, CITY_BOUND * 2, 0.28, 5.2, false, true);
        addBox(scene, mats.white, p + sign * (HALF_ROAD + 0.14), 0.02, 0, 0.22, 0.14, CITY_BOUND * 2, false, false);
        addBox(scene, mats.white, 0, 0.02, p + sign * (HALF_ROAD + 0.14), CITY_BOUND * 2, 0.14, 0.22, false, false);
      }
    }
  }
  // Crosswalk bars at the larger intersections.
  const crossMat = new THREE.MeshBasicMaterial({ color: 0xb7b5a8 });
  for (let x = -3; x <= 3; x++) for (let z = -3; z <= 3; z++) {
    for (let i = -4; i <= 4; i++) {
      addBox(scene, crossMat, x * BLOCK + i * 1.55, 0.035, z * BLOCK + 11.6, 0.8, 0.014, 4.7, false, false);
      addBox(scene, crossMat, x * BLOCK + 11.6, 0.035, z * BLOCK + i * 1.55, 4.7, 0.014, 0.8, false, false);
    }
    // Manhole cover and storm drains add small street-level detail.
    const mx = x * BLOCK + 20, mz = z * BLOCK - 19;
    const manhole = new THREE.Mesh(new THREE.CircleGeometry(0.72, 20), mat(0x56595a, 0.75, 0.35));
    manhole.rotation.x = -Math.PI / 2; manhole.position.set(mx, 0.035, mz); scene.add(manhole);
  }
}
makeRoads();

// Blocks use layered facades, illuminated windows, rooftop plant and varied silhouettes.
const buildingColliders = [];
const facadePalette = [0x9c9284,0x737b7b,0xb6a994,0x77716b,0xb4a38c,0x64747a,0x9c8174,0xd0c1a8,0x5e6668];
const windowLit = [0xffdca2,0xf6c991,0xd6e8df,0xffc880];
const windows = [];
const windowGeo = new THREE.BoxGeometry(1,1,0.12);
function addBuilding(x,z,w,d,h,style=0) {
  const group = new THREE.Group(); group.position.set(x,0,z); scene.add(group);
  const baseColor = facadePalette[Math.floor(rand()*facadePalette.length)];
  const bodyMat = mat(baseColor, 0.87);
  const body = addBox(group, bodyMat, 0, h/2, 0, w, h, d);
  buildingColliders.push({ minX:x-w/2-0.8,maxX:x+w/2+0.8,minZ:z-d/2-0.8,maxZ:z+d/2+0.8 });
  const trimMat = mat(style===2?0x383c3e:0xd1c4ad, 0.66);
  addBox(group, trimMat, 0, h+0.15, 0, w+0.45, 0.3, d+0.45);
  // Recessed, dark windows on the street facades, with a handful of warm occupied rooms.
  const floors = Math.floor(h/3.2), cols = Math.max(2,Math.floor(w/3.25));
  const pane = mat(0x26373e,0.28,0.18), glowMat = mat(windowLit[Math.floor(rand()*windowLit.length)],0.35,0.12);
  const ww = Math.min(1.48,(w-1.6)/cols*0.56), wh = 1.65;
  for(let f=0;f<floors;f++) for(let c=0;c<cols;c++) {
    const px=-w/2+(c+0.5)*w/cols;
    const py=1.65+f*3.1;
    for(const face of [-1,1]) {
      const mz=face*(d/2+0.018);
      const isLit=rand()<0.16;
      addBox(group,isLit?glowMat:pane,px,py,mz,ww,wh,0.09,false,false);
      if(style===1) addBox(group,trimMat,px,py-0.94,mz,ww+0.13,0.11,0.12,false,false);
    }
    if(rand()<0.56) {
      for(const face of [-1,1]) addBox(group,pane,face*(w/2+0.018),py,-d/2+(c+0.5)*d/cols,Math.min(0.1,ww),wh,Math.min(1.1,d/cols*.5),false,false);
    }
  }
  // A strong street-level storefront belt and a few canopies.
  addBox(group,mat(0x30383a,0.32,0.15),0,1.42,d/2+0.06,w-0.5,2.52,0.16,false,false);
  addBox(group,mat([0xc37d55,0x607a79,0xc0a36d,0x7d7770][Math.floor(rand()*4)],0.58),0,2.83,d/2+0.28,w*0.58,0.16,1.05,false);
  for(let q=0;q<Math.max(1,Math.floor(w/10));q++) {
    const xx=-w/2+(q+0.5)*w/Math.max(1,Math.floor(w/10));
    addBox(group,mat(0x252a2b,0.35),xx,3.8,d/2+0.1,0.12,2.7,0.15,false,false);
  }
  // Roof machinery and parapet.
  const roofMat=mat(0x696b66,0.82);
  if(h>15) {
    addBox(group,roofMat,-w*.22,h+.72,-d*.15,w*.25,1.15,d*.28);
    addBox(group,mat(0x535855,0.82),w*.22,h+.5,d*.14,w*.2,.7,d*.22);
    addBox(group,trimMat,0,h+.42,-d/2,w,.32,.38,false);
    if(rand()<.4) { const antenna=new THREE.Mesh(cylGeo,mat(0x555a59,.7));antenna.scale.set(.045,h*.14,.045);antenna.position.set(w*.32,h+h*.07,0);group.add(antenna); }
  }
  return group;
}
function makePalm(x,z,scale=1) {
  const group=new THREE.Group();group.position.set(x,0,z);group.scale.setScalar(scale);scene.add(group);
  const bark=mat(0x705543,.97), frondMats=[mat(0x385b45,.95),mat(0x48664a,.95),mat(0x68744e,.96)];
  const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.3,.48,7,9),bark);trunk.position.y=3.5;trunk.castShadow=true;group.add(trunk);
  for(let i=0;i<9;i++) { const a=i/9*Math.PI*2;const leaf=new THREE.Mesh(new THREE.ConeGeometry(.47,5.6,5),frondMats[i%3]);leaf.position.set(Math.sin(a)*1.8,7.3+Math.sin(i*2)*.24,Math.cos(a)*1.8);leaf.rotation.z=Math.sin(a)*.93;leaf.rotation.x=-Math.cos(a)*.93;leaf.castShadow=true;group.add(leaf); }
}
function makeTree(x,z,scale=1) {
  const g=new THREE.Group();g.position.set(x,0,z);g.scale.setScalar(scale);scene.add(g);
  const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.17,.28,3.5,8),mats.trunk);trunk.position.y=1.75;trunk.castShadow=true;g.add(trunk);
  const crown=new THREE.Mesh(new THREE.SphereGeometry(1.6,10,8),rand()<.5?mats.leaf:mats.leaf2);crown.position.y=4.2;crown.scale.set(1,1.12,.95);crown.castShadow=true;g.add(crown);
  for(let i=0;i<3;i++){const puff=new THREE.Mesh(new THREE.SphereGeometry(.9,8,6),i%2?mats.leaf2:mats.leaf);puff.position.set((rand()-.5)*1.8,4.2+rand()*1.25,(rand()-.5)*1.5);puff.castShadow=true;g.add(puff);}
}
function makeStreetlight(x,z,rot=0) {
  const g=new THREE.Group();g.position.set(x,0,z);g.rotation.y=rot;scene.add(g);
  const pole=mat(0x343b3c,.58,.52), lamp=mat(0xffe6bd,.26);
  const p=new THREE.Mesh(new THREE.CylinderGeometry(.075,.12,7.4,8),pole);p.position.y=3.7;p.castShadow=true;g.add(p);
  const arm=new THREE.Mesh(boxGeo,pole);arm.position.set(.9,7.08,0);arm.scale.set(1.8,.11,.11);arm.rotation.z=-.1;g.add(arm);
  const head=new THREE.Mesh(boxGeo,lamp);head.position.set(1.72,6.92,0);head.scale.set(.52,.13,.35);g.add(head);
  const bulb=new THREE.PointLight(0xffc786,0.48,18,2);bulb.position.set(1.65,6.55,0);g.add(bulb);
}
function makeCity() {
  // A distant cluster of towers builds a recognizable skyline beyond the playable grid.
  for(let i=0;i<21;i++) {
    const x=(rand()-.5)*500,z=-360-rand()*135;
    const h=35+rand()*90,w=16+rand()*27,d=17+rand()*24;
    addBuilding(x,z,w,d,h,2);
  }
  for(let ix=-4;ix<=4;ix++) for(let iz=-4;iz<=4;iz++) {
    const cx=ix*BLOCK,cz=iz*BLOCK;
    if(Math.abs(ix)>3||Math.abs(iz)>3) continue;
    const park=(ix===1&&iz===0)||(ix===-2&&iz===2);
    if(park) {
      addBox(scene,mat(0x66765d,.95),cx,0.02,cz,38,.22,38,false);
      for(let j=0;j<9;j++) makeTree(cx+(rand()-.5)*32,cz+(rand()-.5)*32,.76+rand()*.45);
      for(let j=-2;j<=2;j++) addBox(scene,mat(0x9b947e,.95),cx+j*4,.14,cz,1.25,.04,35,false);
      continue;
    }
    const n=rand()<.38?1:2;
    for(let b=0;b<n;b++) {
      const bw=n===1?27+rand()*8:15+rand()*7,bd=n===1?27+rand()*8:30+rand()*6;
      const ox=n===1?0:(b===0?-10.2:10.2),oz=n===1?0:(rand()-.5)*8;
      const x=cx+ox,z=cz+oz;
      let h=11+rand()*39;
      if((ix===0&&iz<-1)||(ix===-1&&iz===-2)||(ix===1&&iz===-2)) h=37+rand()*60;
      addBuilding(x,z,bw,bd,h,Math.floor(rand()*3));
      // Small rooftop water tanks on low-rise blocks.
      if(h<25&&rand()<.45) { const tank=new THREE.Mesh(cylGeo,mat(0x575d5b,.74));tank.scale.set(1.15,1.8,1.15);tank.position.set(x+bw*.24,h+1,z);tank.castShadow=true;scene.add(tank); }
    }
    // Palm-lined walkways with occasional warm street lamps.
    if(Math.abs(ix)<3&&Math.abs(iz)<3) {
      if(rand()<.74) { makePalm(cx-22,cz-23,.68+rand()*.22);makePalm(cx+22,cz+23,.68+rand()*.22); }
      if(rand()<.36) makeStreetlight(cx-25,cz+4,Math.PI/2);
    }
  }
  // Ocean horizon and low hills lend depth beyond the urban grid.
  const ocean=new THREE.Mesh(new THREE.PlaneGeometry(1800,680),mat(0x506775,.38,.16));ocean.rotation.x=-Math.PI/2;ocean.position.set(0,-.28,-780);scene.add(ocean);
  for(let i=0;i<16;i++) {const hill=new THREE.Mesh(new THREE.SphereGeometry(1,12,8),mat(i%2?0x56646a:0x626d69,.96));hill.scale.set(50+rand()*90,15+rand()*28,55+rand()*70);hill.position.set((rand()-.5)*850,8,-440-rand()*90);scene.add(hill);}
}
makeCity();

// Detailed low-poly vehicles: reflective paint, glasshouse, lighting, wheels and trim.
const vehiclePaints=[0x243b4b,0x94897b,0x38494d,0x9c4337,0xc0ad8e,0x343b43,0x68746f,0x2a3442];
function makeCar({color=0x25394b,police=false,compact=false}={}) {
  const root=new THREE.Group();
  const paint=new THREE.MeshPhysicalMaterial({color,roughness:.27,metalness:.47,clearcoat:.72,clearcoatRoughness:.22});
  const trim=mat(police?0x101719:0x25292a,.3,.43), tireM=mats.rubber, rim=mat(0xb7b9b5,.23,.8);
  const w=compact?1.82:2.08,l=compact?4.15:4.85,h=compact?1.34:1.55;
  addBox(root,paint,0,.68,0,w,.58,l);
  addBox(root,paint,0,1.02,-.48,w*.91,.38,l*.42);
  addBox(root,paint,0,1.07,.95,w*.89,.35,l*.35);
  const cabin=new THREE.Mesh(boxGeo,police?new THREE.MeshPhysicalMaterial({color:0x233541,roughness:.18,metalness:.15,transparent:true,opacity:.62}):mats.glass);
  cabin.position.set(0,1.47,-.25);cabin.scale.set(w*.75,.76,l*.40);cabin.castShadow=true;root.add(cabin);
  // Roof panel and pillars.
  addBox(root,paint,0,1.89,-.27,w*.66,.13,l*.36);
  for(const side of [-1,1]) for(const z of [-.87,.4]) {
    const pillar=new THREE.Mesh(boxGeo,trim);pillar.position.set(side*w*.38,1.47,z);pillar.scale.set(.075,.78,.09);pillar.rotation.x=z>0?-.11:.11;root.add(pillar);
  }
  addBox(root,trim,0,.63,l*.5,w*.68,.18,.09,false);
  for(const side of [-1,1]) {
    const mirror=new THREE.Mesh(boxGeo,paint);mirror.position.set(side*w*.53,1.35,-.67);mirror.scale.set(.24,.16,.3);mirror.castShadow=true;root.add(mirror);
  }
  const wheels=[];
  for(const x of [-w*.52,w*.52]) for(const z of [-l*.32,l*.32]) {
    const wheel=new THREE.Group();wheel.position.set(x,.47,z);root.add(wheel);
    const rubber=new THREE.Mesh(new THREE.CylinderGeometry(.43,.43,.22,16),tireM);rubber.rotation.z=Math.PI/2;rubber.castShadow=true;wheel.add(rubber);
    const hub=new THREE.Mesh(new THREE.CylinderGeometry(.245,.245,.232,12),rim);hub.rotation.z=Math.PI/2;wheel.add(hub);
    const center=new THREE.Mesh(new THREE.CylinderGeometry(.09,.09,.24,10),trim);center.rotation.z=Math.PI/2;wheel.add(center);wheels.push(wheel);
  }
  const headMat=new THREE.MeshStandardMaterial({color:0xfff0cc,emissive:0xffcd76,emissiveIntensity:.3,roughness:.22});
  const tailMat=new THREE.MeshStandardMaterial({color:0xa52d27,emissive:0xea3326,emissiveIntensity:.75,roughness:.25});
  for(const x of [-.68,.68]) {
    addBox(root,headMat,x,.81,-l*.5-.045,.38,.19,.09,false,false);
    addBox(root,tailMat,x,.83,l*.5+.05,.32,.2,.08,false,false);
  }
  if(police) {
    addBox(root,mat(0xe5e6e1,.3),0,1.27,0,w*1.01,.22,l*.88);
    addBox(root,mat(0x151b1e,.32),0,1.40,0,w*.78,.10,.46);
    for(const x of [-.38,.38]) {
      const red=new THREE.MeshStandardMaterial({color:0xef332e,emissive:0xf51b18,emissiveIntensity:2});
      const blue=new THREE.MeshStandardMaterial({color:0x1688ff,emissive:0x126cff,emissiveIntensity:2});
      const r=new THREE.Mesh(boxGeo,red);r.position.set(x,1.48,0);r.scale.set(.23,.12,.17);root.add(r);
      const b=new THREE.Mesh(boxGeo,blue);b.position.set(-x,1.48,0);b.scale.set(.23,.12,.17);root.add(b);
      const lp=new THREE.PointLight(0xff251d,0,8,2);lp.position.set(x,1.7,0);root.add(lp);
      const bp=new THREE.PointLight(0x167cff,0,8,2);bp.position.set(-x,1.7,0);root.add(bp);
    }
    addBox(root,mat(0xcfd4d1,.4),0,1.16,-l*.5-.012,w*.48,.18,.04,false,false);
  }
  root.userData={w,l,h,wheels,police,paint};
  return root;
}
function makePerson() {
  const root=new THREE.Group();
  const jacket=mat(0x344d58,.86), pants=mat(0x22292c,.92), skin=mat(0xb78667,.8), shoe=mat(0x171a1c,.76), hair=mat(0x242322,.92), shirt=mat(0xd0c7ae,.85);
  const torso=new THREE.Mesh(new THREE.CapsuleGeometry(.29,.64,4,8),jacket);torso.position.y=1.26;torso.castShadow=true;root.add(torso);
  const chest=new THREE.Mesh(new THREE.CapsuleGeometry(.17,.48,4,7),shirt);chest.position.set(0,1.29,-.055);chest.castShadow=true;root.add(chest);
  const head=new THREE.Mesh(new THREE.SphereGeometry(.22,12,10),skin);head.position.set(0,1.93,0);head.scale.set(.88,1.12,.92);head.castShadow=true;root.add(head);
  const hairCap=new THREE.Mesh(new THREE.SphereGeometry(.225,12,8,0,Math.PI*2,0,Math.PI*.56),hair);hairCap.position.set(0,2.01,0);root.add(hairCap);
  const legPivots=[],armPivots=[];
  for(const side of [-1,1]) {
    const leg=new THREE.Group();leg.position.set(side*.16,.94,0);root.add(leg);legPivots.push(leg);
    const thigh=new THREE.Mesh(new THREE.CapsuleGeometry(.12,.49,4,7),pants);thigh.position.y=-.35;thigh.castShadow=true;leg.add(thigh);
    const foot=new THREE.Mesh(new THREE.BoxGeometry(.2,.14,.38),shoe);foot.position.set(0,-.72,-.09);foot.castShadow=true;leg.add(foot);
