import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
const runtime='/home/runner/.local/share/omgithub-playwright';
const require=createRequire(runtime+'/package.json');
const {chromium}=require('playwright');
process.env.DISPLAY ||= ':'+readFileSync(runtime+'/display','utf8').trim();
const config=JSON.parse(readFileSync(runtime+'/linux.json','utf8'));
const browser=await chromium.launch({...config.browser.launchOptions,timeout:30000});
const page=await browser.newPage({viewport:{width:1000,height:650}});
const errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.goto('http://127.0.0.1:3002',{waitUntil:'load'});await page.waitForTimeout(2800);
const footHint=await page.locator('#objective-text').innerText();
await page.keyboard.press('e');await page.waitForTimeout(450);
const carHint=await page.locator('#objective-text').innerText();
const controls=await page.locator('#help-card').innerText();
await page.keyboard.down('w');await page.waitForTimeout(800);await page.keyboard.up('w');
const speed=await page.locator('#speed-value').innerText();await page.waitForTimeout(2400);
await page.screenshot({path:'/tmp/opencode/captures/latest.jpg',type:'jpeg',quality:76});
console.log(JSON.stringify({footHint,carHint,controls,speed,errors},null,2));
await browser.close();
EOF

